local SaddlePolishMaker = {}
local PRODUCTS = {
    iron_saddle_polish = { name = "Železna polirka za sedla", ironCost = 1, woodCost = 2, leatherCost = 3, time = 5, cost = 145, prestige = 3, happiness = 2, description = "Železna polirka za sijaj sedel." },
    bronze_saddle_polish = { name = "Bronasta polirka za sedla", bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 7, cost = 350, prestige = 5, happiness = 3, description = "Bronasta polirka za negovana sedla." },
    silver_saddle_polish = { name = "Srebrna polirka za sedla", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 11, cost = 850, prestige = 10, happiness = 4, description = "Srebrna polirka za plemiška sedla." },
    gilded_saddle_polish = { name = "Pozlačena polirka za sedla", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 15, cost = 1820, prestige = 19, happiness = 5, description = "Pozlačena polirka za dvorna sedla." },
    jewel_set_saddle_polish = { name = "Draguljasta polirka za sedla", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 19, cost = 3950, prestige = 35, happiness = 7, description = "Draguljasta polirka za kraljevska sedla." },
    royal_sovereign_saddle_polish = { name = "Kraljevski suverena polirka za sedla", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 26, cost = 8500, prestige = 67, happiness = 13, description = "Suverena polirka z biseri za krono." },
}
local BUILDINGS = {
    saddlepolish_workshop = { name = "Polirna delavnica", cost = { gold = 305, wood = 180, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    saddlepolish_house = { name = "Polirna hiša", cost = { gold = 1135, wood = 360, stone = 260, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_saddlepolish_atelier = { name = "Mojstrski polirni atelje", cost = { gold = 2880, wood = 420, stone = 500, silver = 33, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    sovereign_saddlepolish_palace = { name = "Suverena polirna palača", cost = { gold = 12480, wood = 645, stone = 805, gold = 80, jewel = 18 }, upkeep = 246, qualityBonus = 55, prestigeBonus = 50 },
}
SaddlePolishMaker.ironStock = 10; SaddlePolishMaker.bronzeStock = 8; SaddlePolishMaker.woodStock = 14; SaddlePolishMaker.leatherStock = 16; SaddlePolishMaker.silverStock = 8; SaddlePolishMaker.goldStock = 6; SaddlePolishMaker.jewelStock = 4; SaddlePolishMaker.pearlStock = 4
SaddlePolishMaker.productStock = {}; SaddlePolishMaker.buildings = {}; SaddlePolishMaker.maker = nil; SaddlePolishMaker.activeMaking = {}; SaddlePolishMaker.totalProducts = 0; SaddlePolishMaker.dayTimer = 0
function SaddlePolishMaker.init() SaddlePolishMaker.ironStock=10; SaddlePolishMaker.bronzeStock=8; SaddlePolishMaker.woodStock=14; SaddlePolishMaker.leatherStock=16; SaddlePolishMaker.silverStock=8; SaddlePolishMaker.goldStock=6; SaddlePolishMaker.jewelStock=4; SaddlePolishMaker.pearlStock=4; SaddlePolishMaker.productStock={}; SaddlePolishMaker.buildings={}; SaddlePolishMaker.maker=nil; SaddlePolishMaker.activeMaking={}; SaddlePolishMaker.totalProducts=0; SaddlePolishMaker.dayTimer=0; print("[SaddlePolishMaker] Royal Saddle Polish Maker System initialized (6 products, 4 buildings)") end
function SaddlePolishMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaddlePolishMaker.maker={name=n or ("Polirar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polirar najet: %s (spretnost: %d)",SaddlePolishMaker.maker.name,s),"success") end; return true end
function SaddlePolishMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaddlePolishMaker.build(id) local ok,e=SaddlePolishMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaddlePolishMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaddlePolishMaker.getQualityBonus() local b=0; for _,bd in ipairs(SaddlePolishMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaddlePolishMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SaddlePolishMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SaddlePolishMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SaddlePolishMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SaddlePolishMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SaddlePolishMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaddlePolishMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaddlePolishMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SaddlePolishMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SaddlePolishMaker.buildings==0 then return false,"Potrebna polirna delavnica" end; if not SaddlePolishMaker.maker then return false,"Potreben polirar" end; return true end
function SaddlePolishMaker.make(pt,qty) qty=qty or 1; local ok,e=SaddlePolishMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SaddlePolishMaker.ironStock=SaddlePolishMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SaddlePolishMaker.bronzeStock=SaddlePolishMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SaddlePolishMaker.woodStock=SaddlePolishMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SaddlePolishMaker.leatherStock=SaddlePolishMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SaddlePolishMaker.silverStock=SaddlePolishMaker.silverStock-d.silverCost*qty end; if d.goldCost then SaddlePolishMaker.goldStock=SaddlePolishMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SaddlePolishMaker.jewelStock=SaddlePolishMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SaddlePolishMaker.pearlStock=SaddlePolishMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SaddlePolishMaker.maker then t=math.max(1,t-math.floor(SaddlePolishMaker.maker.skill/13)) end; table.insert(SaddlePolishMaker.activeMaking,{id="saddlepolish_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaddlePolishMaker.completeMaking(m) local q=1.0+(SaddlePolishMaker.getQualityBonus()/100); if SaddlePolishMaker.maker then q=q+(SaddlePolishMaker.maker.skill/140) end; q=math.min(2.5,q); SaddlePolishMaker.productStock[m.productType]=(SaddlePolishMaker.productStock[m.productType] or 0)+m.quantity; SaddlePolishMaker.totalProducts=SaddlePolishMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaddlePolishMaker.maker then SaddlePolishMaker.maker.itemsMade=SaddlePolishMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SaddlePolishMaker.maker.skill=math.min(100,SaddlePolishMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polirka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"saddlepolish.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SaddlePolishMaker.update(dt) if not _G.state then return end; SaddlePolishMaker.dayTimer=SaddlePolishMaker.dayTimer+dt; if SaddlePolishMaker.dayTimer>=30 then SaddlePolishMaker.dayTimer=0; for i=#SaddlePolishMaker.activeMaking,1,-1 do local m=SaddlePolishMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaddlePolishMaker.completeMaking(m); table.remove(SaddlePolishMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaddlePolishMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaddlePolishMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaddlePolishMaker.getStats() return {ironStock=SaddlePolishMaker.ironStock,bronzeStock=SaddlePolishMaker.bronzeStock,woodStock=SaddlePolishMaker.woodStock,leatherStock=SaddlePolishMaker.leatherStock,silverStock=SaddlePolishMaker.silverStock,goldStock=SaddlePolishMaker.goldStock,jewelStock=SaddlePolishMaker.jewelStock,pearlStock=SaddlePolishMaker.pearlStock,productStock=SaddlePolishMaker.productStock,numBuildings=#SaddlePolishMaker.buildings,hasMaker=SaddlePolishMaker.maker~=nil,makerName=SaddlePolishMaker.maker and SaddlePolishMaker.maker.name or "—",makerSkill=SaddlePolishMaker.maker and SaddlePolishMaker.maker.skill or 0,activeMaking=#SaddlePolishMaker.activeMaking,totalProducts=SaddlePolishMaker.totalProducts} end
return SaddlePolishMaker
